int vg_ptt_start(const char *devpath, vg_ptt_event_fn fn, void *arg)
{
  pthread_attr_t attr;
  pthread_t tid;
  int pipefd[2];
  int ret;

  pthread_mutex_lock(&g_lock);

  if (g_running)
    {
      pthread_mutex_unlock(&g_lock);
      return 0;
    }

  if (devpath != NULL && devpath[0] != '\0')
    {
      strncpy(g_devpath, devpath, sizeof(g_devpath) - 1);
      g_devpath[sizeof(g_devpath) - 1] = '\0';
    }

  g_callback = (fn != NULL) ? fn : default_handler;
  g_callback_arg = arg;
  g_stop = false;

  /* 统计清零；状态机在 ptt 线程里按当前电平重新初始化 */

  memset(&g_stats, 0, sizeof(g_stats));
  g_stats.state = g_ptt.state;

  pthread_mutex_unlock(&g_lock);

  /* 唤醒管道在启动前建立，确保 stop 永远不会写到 -1 */

  if (pipe(pipefd) != 0)
    {
      printf("vgptt: pipe failed: %d\n", errno);
      return -errno;
    }

  pthread_mutex_lock(&g_lock);
  g_wakeup_rd = pipefd[0];
  g_wakeup_wr = pipefd[1];
  pthread_mutex_unlock(&g_lock);

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, CONFIG_VG_PTT_STACKSIZE);

  ret = pthread_create(&tid, &attr, ptt_thread, NULL);
  pthread_attr_destroy(&attr);

  if (ret != 0)
    {
      printf("vgptt: thread create failed: %d\n", ret);

      pthread_mutex_lock(&g_lock);
      close(g_wakeup_rd);
      close(g_wakeup_wr);
      g_wakeup_rd = -1;
      g_wakeup_wr = -1;
      pthread_mutex_unlock(&g_lock);

      return -ret;
    }

  pthread_mutex_lock(&g_lock);
  g_thread_valid = true;
  g_running = true;
  pthread_mutex_unlock(&g_lock);

  pthread_detach(tid);
  return 0;
}

