int vg_ptt_stop(int wait_ms)
{
  bool valid;
  int wakeup_wr;
  int waited = 0;

  if (wait_ms <= 0)
    {
      wait_ms = VG_PTT_STOP_DEFAULT_MS;
    }

  pthread_mutex_lock(&g_lock);
  valid = g_thread_valid;
  wakeup_wr = g_wakeup_wr;
  g_stop = true;
  pthread_mutex_unlock(&g_lock);

  if (!valid)
    {
      return 0;
    }

  /* 写一个字节打断 poll；管道满或对端已关都无关紧要，线程仍会看到
   * g_stop。不做错误处理，避免停止路径因为通知失败而卡住。 */

  if (wakeup_wr >= 0)
    {
      char byte = 1;

      (void)write(wakeup_wr, &byte, 1);
    }

  /* 线程已 detach，不能用 pthread_join；按运行标志有界等待。线程退出后
   * 才关闭管道，避免它还在 poll 一个已释放的描述符。 */

  while (waited < wait_ms)
    {
      pthread_mutex_lock(&g_lock);
      if (!g_running)
        {
          g_thread_valid = false;

          /* 读端归线程，线程已退出；这里只回收写端。读端在 start 失败
           * 路径里关闭。 */

          if (g_wakeup_wr >= 0)
            {
              close(g_wakeup_wr);
              g_wakeup_wr = -1;
            }

          pthread_mutex_unlock(&g_lock);
          return 0;
        }

      pthread_mutex_unlock(&g_lock);

      usleep(20 * 1000);
      waited += 20;
    }

