1086	/****************************************************************************
1087	 * Name: sai_samplerate
1088	 *
1089	 * Description:
1090	 *   Set the I2S RX/TX sample rate.
1091	 *
1092	 * Input Parameters:
1093	 *   dev  - Device-specific state data
1094	 *   rate - The I2S sample rate in samples (not bits) per second
1095	 *
1096	 * Returned Value:
1097	 *   Returns the resulting bitrate
1098	 *
1099	 ****************************************************************************/
1100	
1101	static uint32_t sai_samplerate(struct i2s_dev_s *dev, uint32_t rate)
1102	{
1103	  struct stm32f7_sai_s *priv = (struct stm32f7_sai_s *)dev;
1104	
1105	  DEBUGASSERT(priv && rate > 0);
1106	
1107	  /* Call callback to change system clock (needed for STM32F746 Disco) */
1108	
1109	  if (priv->sampleratecb != NULL)
1110	    {
1111	      priv->frequency = priv->sampleratecb(dev, rate);
1112	    }
1113	  else
1114	    {
1115	      i2sinfo("No Sample Rate CB set!\n");
1116	    }
1117	
1118	  /* Save the new sample rate and update the divider */
1119	
1120	  priv->samplerate = rate;
1121	  sai_mckdivider(priv);
1122	
1123	  return sai_getbitrate(priv);
1124	}
