1126	/****************************************************************************
1127	 * Name: sai_datawidth
1128	 *
1129	 * Description:
1130	 *   Set the I2S data width.  The bitrate is determined by
1131	 *   sample_rate * data_width.
1132	 *
1133	 * Input Parameters:
1134	 *   dev   - Device-specific state data
1135	 *   width - The I2S data with in bits.
1136	 *
1137	 * Returned Value:
1138	 *   Returns the resulting bitrate
1139	 *
1140	 ****************************************************************************/
1141	
1142	static uint32_t sai_datawidth(struct i2s_dev_s *dev, int bits)
1143	{
1144	  struct stm32f7_sai_s *priv = (struct stm32f7_sai_s *)dev;
1145	  uint32_t setbits;
1146	
1147	  DEBUGASSERT(priv && bits >= 8);
1148	
1149	  switch (bits)
1150	    {
1151	      case 8:
1152	        setbits = SAI_CR1_DS_8BITS;
1153	        break;
1154	
1155	      case 16:
1156	        setbits = SAI_CR1_DS_16BITS;
1157	        break;
1158	
1159	      case 32:
1160	        setbits = SAI_CR1_DS_32BITS;
1161	        break;
1162	
1163	      default:
1164	        i2serr("ERROR: Unsupported or invalid data width: %d\n", bits);
1165	        return 0;
1166	    }
1167	
1168	  sai_modifyreg(priv, STM32F7_SAI_CR1_OFFSET, SAI_CR1_DS_MASK, setbits);
1169	
1170	  sai_modifyreg(priv, STM32F7_SAI_FRCR_OFFSET,
1171	                SAI_FRCR_FSALL_MASK | SAI_FRCR_FRL_MASK,
1172	                SAI_FRCR_FSALL(bits) | SAI_FRCR_FRL(bits * 2));
1173	
1174	  /* Save the new data width */
1175	
1176	  priv->datalen = bits;
1177	
1178	  return sai_getbitrate(priv);
1179	}
