1381	/****************************************************************************
1382	 * Name: sai_buf_allocate
1383	 *
1384	 * Description:
1385	 *   Allocate a buffer container by removing the one at the head of the
1386	 *   free list
1387	 *
1388	 * Input Parameters:
1389	 *   priv - SAI state instance
1390	 *
1391	 * Returned Value:
1392	 *   A non-NULL pointer to the allocate buffer container on success; NULL if
1393	 *   there are no available buffer containers.
1394	 *
1395	 * Assumptions:
1396	 *   The caller does NOT have exclusive access to the SAI state structure.
1397	 *   That would result in a deadlock!
1398	 *
1399	 ****************************************************************************/
1400	
1401	static struct sai_buffer_s *sai_buf_allocate(struct stm32f7_sai_s *priv)
1402	{
1403	  struct sai_buffer_s *bfcontainer;
1404	  irqstate_t flags;
1405	
1406	  /* Set aside a buffer container.  By doing this, we guarantee that we will
1407	   * have at least one free buffer container.
1408	   */
1409	
1410	  nxsem_wait_uninterruptible(&priv->bufsem);
1411	
1412	  /* Get the buffer from the head of the free list */
1413	
1414	  flags = enter_critical_section();
1415	  bfcontainer = priv->freelist;
1416	  DEBUGASSERT(bfcontainer);
1417	
1418	  /* Unlink the buffer from the freelist */
1419	
1420	  priv->freelist = bfcontainer->flink;
1421	  leave_critical_section(flags);
1422	  return bfcontainer;
1423	}
1424	
1425	/****************************************************************************
1426	 * Name: sai_buf_free
1427	 *
1428	 * Description:
1429	 *   Free buffer container by adding it to the head of the free list
1430	 *
1431	 * Input Parameters:
1432	 *   priv - SAI state instance
1433	 *   bfcontainer - The buffer container to be freed
1434	 *
1435	 * Returned Value:
1436	 *   None
1437	 *
1438	 * Assumptions:
1439	 *   The caller has exclusive access to the SAI state structure
1440	 *
1441	 ****************************************************************************/
1442	
1443	static void sai_buf_free(struct stm32f7_sai_s *priv,
1444	                         struct sai_buffer_s *bfcontainer)
1445	{
1446	  irqstate_t flags;
1447	
1448	  /* Put the buffer container back on the free list */
1449	
1450	  flags = enter_critical_section();
1451	  bfcontainer->flink  = priv->freelist;
1452	  priv->freelist = bfcontainer;
1453	  leave_critical_section(flags);
1454	
1455	  /* Wake up any threads waiting for a buffer container */
1456	
1457	  nxsem_post(&priv->bufsem);
1458	}
1459	
1460	/****************************************************************************
1461	 * Name: sai_buf_initialize
1462	 *
1463	 * Description:
1464	 *   Initialize the buffer container allocator by adding all of the
1465	 *   pre-allocated buffer containers to the free list
