1095	/****************************************************************************
1096	 * Name: sai_buf_allocate
1097	 ****************************************************************************/
1098	
1099	static struct sai_buffer_s *sai_buf_allocate(struct stm32h7_sai_s *priv)
1100	{
1101	  struct sai_buffer_s *bfcontainer;
1102	  irqstate_t flags;
1103	
1104	  /* Set aside a buffer container.  By doing this, we guarantee that we will
1105	   * have at least one free buffer container.
1106	   */
1107	
1108	  nxsem_wait_uninterruptible(&priv->bufsem);
1109	
1110	  /* Get the buffer from the head of the free list */
1111	
1112	  flags = enter_critical_section();
1113	  bfcontainer = priv->freelist;
1114	  DEBUGASSERT(bfcontainer);
1115	
1116	  /* Unlink the buffer from the freelist */
1117	
1118	  priv->freelist = bfcontainer->flink;
1119	  leave_critical_section(flags);
1120	  return bfcontainer;
1121	}
