1123	/****************************************************************************
1124	 * Name: sai_buf_free
1125	 ****************************************************************************/
1126	
1127	static void sai_buf_free(struct stm32h7_sai_s *priv,
1128	                         struct sai_buffer_s *bfcontainer)
1129	{
1130	  irqstate_t flags;
1131	
1132	  /* Put the buffer container back on the free list */
1133	
1134	  flags = enter_critical_section();
1135	  bfcontainer->flink  = priv->freelist;
1136	  priv->freelist = bfcontainer;
1137	  leave_critical_section(flags);
1138	
1139	  /* Wake up any threads waiting for a buffer container */
1140	
1141	  nxsem_post(&priv->bufsem);
1142	}
